-- V5 — bookmark.memo → note 이름 변경의 1단계(넓히기). 서비스를 멈추지 않으려고 한 번에 RENAME하지 않는다.
-- 새 컬럼을 NULL 허용으로 추가하고 지금 값을 복사만 한다. 옛 서버는 memo만 읽고 쓰므로 아무 영향이 없다.
-- 다음 배포(같은 커밋의 코드)는 memo·note 둘 다에 쓰고 읽기는 아직 memo다.
ALTER TABLE bookmark ADD COLUMN note VARCHAR(200) NULL AFTER memo;

UPDATE bookmark SET note = memo;

package org.example.bookmark;

import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
@Transactional
class BookmarkSetControllerTest {
    @Autowired MockMvc mvc;
    @Autowired ObjectMapper mapper;
    @Autowired JdbcTemplate jdbc;
    @Autowired EntityManager em;

    @Test
    void storesOnceWithMemoAndChecksFolderOwnership() throws Exception {
        var first = mvc.perform(put("/api/posts/2/bookmark")
                        .header("Authorization", "Bearer tok-kimjava")
                        .contentType("application/json")
                        .content("{\"memo\":\"[북마크실습] 복습\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.postId").value(2))
                .andExpect(jsonPath("$.bookmarked").value(true))
                .andExpect(jsonPath("$.memo").value("[북마크실습] 복습"))
                .andReturn();
        long id = mapper.readTree(first.getResponse().getContentAsString()).get("bookmarkId").asLong();
        mvc.perform(put("/api/posts/2/bookmark")
                        .header("Authorization", "Bearer tok-kimjava")
                        .contentType("application/json")
                        .content("{\"memo\":\"[북마크실습] 복습\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.bookmarkId").value(id));
        mvc.perform(put("/api/posts/2/bookmark")
                        .header("Authorization", "Bearer tok-kimjava")
                        .contentType("application/json")
                        .content("{\"folderId\":11}"))
                .andExpect(status().isNotFound());
        em.flush();
        assertEquals(1L, jdbc.queryForObject(
                "SELECT COUNT(*) FROM bookmark WHERE member_id=2 AND post_id=2", Long.class));
        assertEquals("[북마크실습] 복습", jdbc.queryForObject(
                "SELECT note FROM bookmark WHERE member_id=2 AND post_id=2", String.class));
    }

    @Test
    void rejectsBadInputAndUnavailablePost() throws Exception {
        mvc.perform(put("/api/posts/2/bookmark")
                        .header("Authorization", "Bearer tok-kimjava")
                        .contentType("application/json").content("{\"memo\":123}"))
                .andExpect(status().isBadRequest());
        mvc.perform(put("/api/posts/2/bookmark")
                        .header("Authorization", "Bearer tok-kimjava")
                        .contentType("application/json").content("{\"memo\":\"" + "x".repeat(201) + "\"}"))
                .andExpect(status().isBadRequest());
        mvc.perform(put("/api/posts/999999/bookmark")
